import sys, re

path = sys.argv[1]
with open(path, encoding='utf-8') as f:
    text = f.read()

# Strip comments (non-greedy, no braces expected inside comments in this file)
text = re.sub(r'/\*.*?\*/', '', text, flags=re.S)

blocks = []  # (selector_text, body_text) for depth-0 rule blocks
depth = 0
buf_selector = []
body_start = None
i = 0
n = len(text)
while i < n:
    ch = text[i]
    if ch == '{':
        if depth == 0:
            selector_text = ''.join(buf_selector)
            buf_selector = []
            body_start = i + 1
        depth += 1
    elif ch == '}':
        depth -= 1
        if depth == 0:
            body_text = text[body_start:i]
            blocks.append((selector_text, body_text))
    else:
        if depth == 0:
            buf_selector.append(ch)
    i += 1

# class_name -> list of (block_index, set_of_property_names)
class_props = {}
bare_re = re.compile(r'^\.[a-zA-Z0-9_-]+$')

for idx, (sel_text, body_text) in enumerate(blocks):
    sel_text = sel_text.strip()
    if sel_text.startswith('@'):
        continue  # at-rule (media/keyframes/etc.), not a selector block
    selectors = [s.strip() for s in sel_text.split(',')]
    selectors = [s for s in selectors if s]
    props = set()
    for decl in body_text.split(';'):
        decl = decl.strip()
        if not decl or ':' not in decl:
            continue
        prop = decl.split(':', 1)[0].strip()
        if prop:
            props.add(prop)
    for s in selectors:
        if bare_re.match(s):
            class_props.setdefault(s, []).append((idx, props))

conflicts = []
for cls, occurrences in class_props.items():
    if len(occurrences) < 2:
        continue
    # check pairwise overlap
    conflict_found = False
    overlap_props = set()
    for a in range(len(occurrences)):
        for b in range(a + 1, len(occurrences)):
            inter = occurrences[a][1] & occurrences[b][1]
            if inter:
                conflict_found = True
                overlap_props |= inter
    if conflict_found:
        conflicts.append((cls, sorted(overlap_props)))

conflicts.sort()
for cls, props in conflicts:
    print(f"{cls.lstrip('.')} (overlapping: {', '.join(props)})")

